insert into sector_profiles (settore, version, status, pack, changelog)
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_preparazione', 'Come mi preparo alla ceretta?', $q97es6z$["come mi devo preparare per la ceretta","cosa devo fare prima della ceretta","devo depilarmi prima della ceretta","quanto devono essere lunghi i peli per la ceretta","i peli devono essere lunghi per la ceretta"]$q97es6z$::jsonb, 'Per la ceretta i peli devono avere una certa lunghezza per essere rimossi bene: l''estetista le indica quella giusta. Di solito si evita di radersi nel periodo prima; per qualunque dubbio chieda al centro.', $qfke6gi${}$qfke6gi$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'La ceretta fa male?', $qy2eluf$["fa male la ceretta","la ceretta e dolorosa","si sente dolore con la ceretta","la ceretta da fastidio"]$qy2eluf$::jsonb, 'La ceretta può dare un po'' di fastidio, che cambia molto da persona a persona e dalla zona trattata. L''estetista procede con calma e può darle indicazioni per renderla più sopportabile.', $qc8zxdm${}$qc8zxdm$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'Ogni quanto si fa la ceretta?', $qmvtcee$["ogni quanto va fatta la ceretta","ogni quanto devo fare la ceretta","ogni quanto si rifa la ceretta","ogni quanto tempo si fa la ceretta"]$qmvtcee$::jsonb, 'La ricrescita è diversa da persona a persona e da zona a zona: l''estetista può indicarle il ritmo più adatto a lei.', $qg785mg${}$qg785mg$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'Come funziona l''epilazione laser?', $qu2ctwx$["come funziona il laser","come funziona il laser per i peli","in cosa consiste l epilazione laser","come funziona la luce pulsata","cos e l epilazione laser"]$qu2ctwx$::jsonb, 'L''epilazione laser, o a luce pulsata, utilizza un''energia luminosa che agisce sul pelo per ridurne la ricrescita. Servono più sedute e una valutazione iniziale, e i risultati variano da persona a persona: non si possono garantire.', $q6ovalc${}$q6ovalc$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'Quante sedute servono per il laser?', $q070h8x$["quante sedute di laser servono","quante sedute servono per l epilazione laser","quante sedute ci vogliono per il laser","quante sedute servono per eliminare i peli"]$q070h8x$::jsonb, 'Il numero di sedute dipende dalla zona, dal tipo di pelo e dalla pelle di ciascuna persona. Dopo la valutazione iniziale la professionista del centro può darle un''indicazione per il suo caso.', $q0pyqsd${}$q0pyqsd$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'Il laser toglie i peli per sempre?', $qwo02kv$["i peli ricrescono dopo il laser","il laser e definitivo","l epilazione laser e definitiva","dopo il laser i peli non tornano piu","i risultati del laser sono definitivi"]$qwo02kv$::jsonb, 'Il laser riduce progressivamente la ricrescita, ma i risultati cambiano da persona a persona e nessun centro può garantire l''eliminazione totale. Per il suo caso è meglio parlarne con la professionista in fase di valutazione.', $qit6ic3${}$qit6ic3$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'Meglio ceretta o laser?', $q2f48n1$["meglio la ceretta o il laser","meglio il laser o la ceretta","differenza tra ceretta e laser","che differenza c e tra ceretta e laser","ceretta o laser quale scegliere"]$q2f48n1$::jsonb, 'Sono due metodi diversi: la ceretta rimuove il pelo temporaneamente, il laser punta a ridurne la ricrescita nel tempo con più sedute. La scelta dipende dalle sue esigenze e dalla sua pelle: l''estetista può orientarla in una consulenza.', $qyobv71${}$qyobv71$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'Cos''è la pressoterapia?', $qa3v0si$["cosa e la pressoterapia","come funziona la pressoterapia","in cosa consiste la pressoterapia","a cosa serve la pressoterapia","che cos e la pressoterapia"]$qa3v0si$::jsonb, 'La pressoterapia è un trattamento di benessere che con apparecchiature a compressione sulle gambe o altre zone dà una sensazione di leggerezza e di drenaggio. È un trattamento estetico: non sostituisce visite o terapie mediche.', $qogqaes${}$qogqaes$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'Come funziona la pulizia del viso?', $qt4g2ru$["in cosa consiste la pulizia viso","cosa si fa nella pulizia del viso","come funziona la pulizia viso","cos e la pulizia del viso","come si svolge la pulizia del viso"]$qt4g2ru$::jsonb, 'La pulizia del viso comprende in genere detersione, vapore o preparazione della pelle, rimozione delle impurità e una maschera o crema finale. Le fasi esatte dipendono dal centro e dal tipo di pelle.', $ql7unxn${}$ql7unxn$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'Ogni quanto si fa la pulizia del viso?', $qtw7f8c$["ogni quanto va fatta la pulizia viso","ogni quanto devo fare la pulizia del viso","ogni quanto tempo si fa la pulizia del viso","ogni quanto si fa la pulizia viso"]$qtw7f8c$::jsonb, 'Dipende dal tipo di pelle e dalle abitudini: l''estetista può consigliarle una frequenza adatta dopo averla vista in cabina.', $qqohrkw${}$qqohrkw$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'Cos''è il semipermanente?', $qz5rf44$["cosa e il semipermanente","come funziona il semipermanente","in cosa consiste il semipermanente","cos e lo smalto semipermanente","che differenza c e tra smalto e semipermanente"]$qz5rf44$::jsonb, 'Il semipermanente è uno smalto che si asciuga con una lampada e tiene più a lungo di uno smalto normale; si rimuove poi con un procedimento specifico in centro. La durata varia da persona a persona.', $qtnj0cp${}$qtnj0cp$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'Il semipermanente rovina le unghie?', $q9tb4br$["il semipermanente danneggia le unghie","il semipermanente fa male alle unghie","rovina le unghie il semipermanente","il semipermanente e dannoso","il gel rovina le unghie"]$q9tb4br$::jsonb, 'Se applicato e rimosso correttamente da una professionista, il semipermanente è in genere ben tollerato; è importante non strappare lo smalto da soli. Per unghie fragili o problemi particolari è meglio chiedere all''estetista.', $qzhmwfv${}$qzhmwfv$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'Differenza tra ricostruzione unghie e semipermanente', $qyv4s4h$["che differenza c e tra ricostruzione e semipermanente","differenza tra gel e semipermanente","ricostruzione o semipermanente","cos e la ricostruzione unghie","come funziona la ricostruzione unghie"]$qyv4s4h$::jsonb, 'Il semipermanente è uno smalto resistente; la ricostruzione, in gel o acrilico, aggiunge o rinforza la struttura dell''unghia. L''estetista può indicarle quale soluzione è più adatta alle sue unghie.', $qjg3y2k${}$qjg3y2k$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'Ogni quanto si fa il refill delle ciglia?', $qa7xmgl$["ogni quanto va fatto il refill delle ciglia","ogni quanto si ritoccano le extension","ogni quanto si rifanno le extension ciglia","ogni quanto bisogna fare il refill","ogni quanto tempo il ritocco delle extension"]$qa7xmgl$::jsonb, 'Le extension seguono il ciclo naturale delle ciglia, quindi servono ritocchi periodici: la frequenza dipende da ciascuna persona e la indica l''estetista.', $qdjxhy5${}$qdjxhy5$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'Come funzionano le extension ciglia?', $qg339cd$["cosa sono le extension ciglia","in cosa consistono le extension ciglia","come si applicano le extension","come funziona l applicazione delle ciglia","extension ciglia cosa sono"]$qg339cd$::jsonb, 'Le extension ciglia sono ciglia sintetiche applicate una per una su quelle naturali, con tecniche diverse (per esempio pelo a pelo o volume). L''applicazione richiede tempo e occhi chiusi per tutta la seduta; ne parli con l''estetista per scegliere effetto e stile.', $qsvar5a${}$qsvar5a$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'Cos''è la laminazione delle ciglia?', $qcsuufb$["cosa e la laminazione ciglia","come funziona la laminazione ciglia","in cosa consiste la laminazione delle ciglia","cos e il lash lift","laminazione ciglia cosa e"]$qcsuufb$::jsonb, 'La laminazione è un trattamento che dà alle ciglia naturali una curvatura e un aspetto più definito, senza aggiungere ciglia finte. Effetto e durata variano da persona a persona.', $qxgk18b${}$qxgk18b$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'Cos''è il microblading?', $qbtdgrb$["cosa e il microblading","come funziona il microblading","in cosa consiste il microblading","cos e la dermopigmentazione","cos e il trucco semipermanente"]$qbtdgrb$::jsonb, 'Il microblading è un trattamento di dermopigmentazione che disegna le sopracciglia depositando pigmento nella pelle, con una tecnica manuale. È un trattamento che richiede una valutazione preliminare con la professionista; durata e risultato variano da persona a persona.', $qdwycmo${}$qdwycmo$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'Quanto dura un massaggio?', $q4ofymx$["quanto dura il massaggio","quanto dura un massaggio rilassante","quanto tempo dura un massaggio","quanto tempo ci vuole per un massaggio"]$q4ofymx$::jsonb, 'La durata dipende dal tipo di massaggio e dalla zona trattata: i dettagli esatti li trova nel listino del centro o può chiederli al team.', $qphmhie${}$qphmhie$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'Il massaggio estetico è un trattamento medico?', $q7rdm3o$["il massaggio e terapeutico","il massaggio cura i dolori","il massaggio decontratturante cura","il massaggio estetico e terapeutico","il massaggio fa passare il mal di schiena"]$q7rdm3o$::jsonb, 'I massaggi proposti da un centro estetico sono trattamenti di benessere e non hanno finalità terapeutiche: per dolori o problemi di salute è meglio rivolgersi al medico o a un fisioterapista.', $qt17kh0${}$qt17kh0$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'Cos''è il peeling viso?', $qr9g11t$["cosa e il peeling","come funziona il peeling","in cosa consiste il peeling viso","che cos e il peeling","cos e il peeling chimico"]$qr9g11t$::jsonb, 'Il peeling è un trattamento che favorisce l''esfoliazione dello strato superficiale della pelle del viso. In un centro estetico si usano prodotti adatti all''uso estetico: la professionista valuta la pelle prima di procedere.', $q03sc5b${}$q03sc5b$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'Cos''è un trattamento anticellulite?', $qcsu7qq$["come funziona il trattamento anticellulite","cosa e il trattamento anticellulite","il trattamento anticellulite funziona","come funziona la cavitazione","cos e la cavitazione"]$qcsu7qq$::jsonb, 'I trattamenti anticellulite o per il corpo sono pensati per il benessere e l''aspetto della pelle, spesso combinando apparecchiature e massaggi. I risultati variano da persona a persona e non si possono garantire.', $qi3gzug${}$qi3gzug$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'Come funziona l''abbronzatura spray?', $quj28by$["cos e l abbronzatura spray","come funziona lo spray tan","abbronzatura spray come funziona","come funziona l abbronzatura istantanea"]$quj28by$::jsonb, 'L''abbronzatura spray colora temporaneamente la pelle senza esporla ai raggi UV. Il centro le dà le indicazioni su come prepararsi e come mantenere il colore.', $q1hthc0${}$q1hthc0$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'Quanto dura il semipermanente?', $qpfydcv$["quanto dura lo smalto semipermanente","quanto tiene il semipermanente","quanto resiste il semipermanente","quanto dura il gel sulle unghie"]$qpfydcv$::jsonb, 'La tenuta dipende dalle unghie e dall''uso quotidiano delle mani: varia da persona a persona e l''estetista può darle un''indicazione.', $qtl2kq9${}$qtl2kq9$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'Posso fare un trattamento estetico se ho una condizione di salute?', $qjkd4di$["ci sono controindicazioni ai trattamenti estetici","ci sono controindicazioni","chi non puo fare i trattamenti","quali sono le controindicazioni","ci sono effetti collaterali"]$qjkd4di$::jsonb, 'Alcuni trattamenti possono non essere adatti in presenza di particolari condizioni, e questo lo valuta caso per caso la professionista del centro, con l''eventuale parere del medico. Prima del trattamento le verrà chiesto di segnalare eventuali condizioni o farmaci.', $qlih2tm${}$qlih2tm$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_preparazione', 'Cosa devo fare prima del laser?', $qe9c390$["come mi preparo al laser","come mi devo preparare per il laser","devo radermi prima del laser","devo depilarmi prima del laser","cosa devo fare prima dell epilazione laser"]$qe9c390$::jsonb, 'Il centro le darà indicazioni precise prima della prima seduta, per esempio sulla preparazione della zona e sull''esposizione al sole. Segua quelle del centro e, in caso di dubbi, chieda alla professionista.', $qmpkdqc${}$qmpkdqc$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_preparazione', 'Cosa devo portare per un trattamento?', $qhrt1rp$["cosa devo portare al trattamento","devo portare qualcosa","cosa serve portare in centro","devo portare l asciugamano","cosa devo portare per il massaggio"]$qhrt1rp$::jsonb, 'Di solito non serve portare nulla di particolare; se il trattamento richiede qualcosa, il centro glielo comunica in fase di prenotazione.', $q9pphwc${}$q9pphwc$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_preparazione', 'Cosa devo fare dopo un trattamento?', $qnby83q$["cosa devo fare dopo il trattamento","cosa non devo fare dopo il trattamento","indicazioni dopo il trattamento","cosa evitare dopo il trattamento","consigli dopo il trattamento"]$qnby83q$::jsonb, 'Dopo ogni trattamento il centro dà indicazioni specifiche per il suo caso: le segua con attenzione. Per qualunque disturbo nei giorni successivi contatti direttamente il centro.', $q9yphnv${}$q9yphnv$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_buoni_regalo', 'Come funziona un buono regalo?', $q6o3c3y$["come funziona la gift card","come si usa un buono regalo","un buono regalo ha una scadenza","come regalare un trattamento","come si regala un trattamento"]$q6o3c3y$::jsonb, 'I buoni regalo, dove disponibili, permettono di regalare un trattamento o un importo da usare in centro. Importi, validità e modalità dipendono dal singolo centro: le conferma il team.', $qyadn8w${}$qyadn8w$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'Gli uomini possono fare i trattamenti estetici?', $qnh8c70$["trattate anche gli uomini","i trattamenti sono anche per uomo","un uomo puo fare la ceretta","ci sono trattamenti per uomo","anche gli uomini vengono in un centro estetico"]$qnh8c70$::jsonb, 'I trattamenti estetici sono pensati sia per donne sia per uomini; quali trattamenti siano disponibili dipende dal centro, che le conferma il team.', $qcpbvax${}$qcpbvax$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('estetista', 1, 'production', 'info_trattamenti', 'Posso fare i trattamenti estetici a una ragazza minorenne?', $qwbg0uz$["mia figlia puo fare la ceretta","ragazza minorenne trattamenti estetici","mia figlia minorenne puo fare il semipermanente","a che eta si puo fare la ceretta"]$qwbg0uz$::jsonb, 'Per le minorenni le regole dipendono dal trattamento e dal centro, e di solito serve l''accompagnamento o il consenso di un genitore: lo verifichi direttamente con il team.', $qsufrlq${}$qsufrlq$::jsonb);
insert into sector_test_scenarios (settore, codice, categoria, scenario) values ('estetista', 'ES01', 'BOOKING', $quczvv3${"scenario":{"input":"Buongiorno, vorrei prenotare una pulizia viso","expected":{"intent":"prenota_trattamento","entities":{"servizio":"pulizia_viso"},"action":"ask_missing_information","next_question":"nome_cliente","safety":"LOW"},"tenant":{"campi":["nome_cliente","sintomo"],"haCalendario":true,"info_generali":{"indirizzo":"via dei gigli 7","prezzi_note":"pulizia viso 45 euro, ceretta gambe intere 28 euro, pacchetto 6 sedute laser ascelle 150 euro","altre_informazioni":"parcheggio gratuito nel cortile, accettiamo satispay e carte, buoni regalo disponibili"}}}}$quczvv3$::jsonb) on conflict (settore, codice) do update set categoria = excluded.categoria, scenario = excluded.scenario;
