insert into sector_test_scenarios (settore, codice, categoria, scenario) values ('estetista', 'ES04', 'BOOKING', $q2yt04z${"scenario":{"input":"avete posto domani pomeriggio?","expected":{"intent":"prenota_trattamento","entities":{"giorno":"domani","fascia_oraria":"pomeriggio"},"action":"ask_missing_information","next_question":"servizio"},"tenant":{"campi":["nome_cliente","sintomo"],"haCalendario":true,"info_generali":{"indirizzo":"via dei gigli 7","prezzi_note":"pulizia viso 45 euro, ceretta gambe intere 28 euro, pacchetto 6 sedute laser ascelle 150 euro","altre_informazioni":"parcheggio gratuito nel cortile, accettiamo satispay e carte, buoni regalo disponibili"}}}}$q2yt04z$::jsonb) on conflict (settore, codice) do update set categoria = excluded.categoria, scenario = excluded.scenario;
